const e=[{id:1,icon:"Flame",accent:"#dc2626",title:"النار ومخاطرها",subtitle:"كيف نحمي أنفسنا من النار",grades:"1-2",ages:"6-8",summary:"النار تفاعلٌ كيميائي بين ثلاثة أشياء: الحرارة والوقود والأكسجين. إذا غاب واحدٌ منها، تنطفئ النار.",blocks:[{heading:"مثلث النار",body:"تتكوّن النار من ثلاثة أشياء: الحرارة والوقود والأكسجين.",image:"media/images/fire_triangle.png"},{heading:"قف، انبطح، تدحرج",body:"إذا اشتعلت النار في ملابسك، فلا تركض! قف، وألقِ بنفسك على الأرض، وغطِّ وجهك بيديك، وتدحرج على الأرض حتى تنطفئ النار.",image:"media/images/stop_drop_roll.png"},{heading:"الخروج الآمن",body:"اعرف طرق الخروج. إذا كان هناك دخان، فانخفض وازحف على يديك وركبتيك. وفي الخارج، قف عند نقطة التجمع وأخبر أحد الكبار.",image:"media/images/fire_exit.png"}],examples:["اختبر جهاز إنذار الدخان كل شهر مع الكبار.","ضع مع عائلتك خطةً للخروج من المنزل.","احفظ الرقم 115.","اعرف نقطة التجمع في مدرستك."],tips:["لا تلعب بأعواد الثقاب والولّاعة.","إذا رأيت دخانًا، فانخفض.","اعرف دائمًا طريقين للخروج."],warnings:["أثناء الحريق، لا تختبئ أبدًا تحت السرير أو داخل الخزانة! فلن يستطيع فريق الدفاع المدني أن يراك. اخرج وأخبر أحد الكبار."],realCase:"في إحدى المدارس، رأى تلميذٌ دخانًا، فأخبر معلّمه فورًا، وخرج الجميع بسلام.",video:"media/videos/lesson_fire.mp4",game:{instruction:"أيّ هذه التصرفات صحيحة أثناء الحريق؟",items:[{text:"قف، انبطح، تدحرج",emoji:"🔄",correct:!0},{text:"اركض عندما تشتعل النار في ملابسك",emoji:"🏃",correct:!1},{text:"ابقَ منخفضًا تحت الدخان",emoji:"🐢",correct:!0},{text:"استخدم المصعد",emoji:"🛗",correct:!1}]},activity:{prompt:"أنت في المنزل وترى نارًا في المطبخ. ماذا ستفعل؟",image:"media/images/activity_fire.png",options:[{text:"أخرج من المنزل فورًا، وأخبر أحد الكبار، ونتصل بالرقم 115",correct:!0,feedback:"الخروج فورًا وإخبار أحد الكبار والاتصال بالرقم 115 هو التصرّف الآمن."},{text:"أحاول إطفاء النار بالماء",correct:!1,feedback:"الأطفال لا يُطفئون النار، والماء على الزيت المشتعل خطر؛ اخرج وأخبر أحد الكبار."},{text:"أختبئ",correct:!1,feedback:"إذا اختبأت فلن يستطيع فريق الدفاع المدني أن يراك؛ اخرج وأخبر أحد الكبار."},{text:"أبقى هناك وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ اخرج من المنزل فورًا وأخبر أحد الكبار."}]},quiz:[{question:"إذا اشتعلت النار في ملابسك، فماذا تفعل؟",options:[{text:"أركض",correct:!1,feedback:"الركض يجعل النار أكبر!"},{text:"أتوقّف، وألقي بنفسي على الأرض، وأتدحرج",correct:!0,feedback:"أحسنت!"},{text:"أبكي",correct:!1,feedback:"البكاء لا يطفئ النار."}]},{question:"ما عناصر النار الثلاثة؟",options:[{text:"الحرارة، الوقود، الأكسجين",correct:!0,feedback:"الحرارة والوقود والأكسجين معًا تكوّن مثلث النار."},{text:"الماء، الرياح، الحرارة",correct:!1,feedback:"لا. النار تحتاج إلى الحرارة والوقود والأكسجين، والماء ليس منها. ولا يُسكب الماء أبدًا على زيت مشتعل أو على الأجهزة الكهربائية."},{text:"الدخان، الماء، الثلج",correct:!1,feedback:"الدخان والماء والثلج لا تكوّن النار؛ فالنار تحتاج إلى الحرارة والوقود والأكسجين."}],explanation:"تتكوّن النار من ثلاثة أشياء: الحرارة والوقود والأكسجين. وإذا غاب واحدٌ منها، تنطفئ النار."},{question:"ما رقم الدفاع المدني؟",options:[{text:"115",correct:!0,feedback:"الرقم 115 هو رقم الدفاع المدني، وقد حفظته جيدًا!"},{text:"122",correct:!1,feedback:"لا، الرقم 122 هو رقم الإسعاف."},{text:"9-1-1",correct:!1,feedback:"لا، هذا رقم الطوارئ في أمريكا، وليس في كوردستان."}],explanation:"في كوردستان، الرقم 115 هو رقم الدفاع المدني. احفظ هذا الرقم!"}]},{id:2,icon:"Activity",accent:"#ea580c",title:"الزلزال",subtitle:"كيف نحمي أنفسنا أثناء الزلزال",grades:"1-2",ages:"6-8",summary:"الزلزال ظاهرةٌ طبيعية. لا نستطيع أن نوقفه، لكننا نستطيع أن نحمي أنفسنا.",blocks:[{heading:"انخفض، احتمِ، تمسّك",body:"انزل على ركبتيك، واحتمِ تحت طاولةٍ متينة، وأمسك ساق الطاولة جيدًا حتى ينتهي الاهتزاز. وإذا لم تكن هناك طاولة، فاجلس على ركبتيك بجانب جدارٍ بعيد عن النوافذ، واحمِ رأسك ورقبتك بيديك.",image:"media/images/drop_cover_hold.png"},{heading:"ابتعد عن الزجاج",body:"الزجاج ينكسر ويمكن أن يجرحك. ابتعد عن النوافذ والمرايا، وعن الأشياء الثقيلة التي يمكن أن تسقط.",image:"media/images/earthquake_glass.png"},{heading:"بعد الزلزال",body:"بعد أن ينتهي الاهتزاز، اخرج بهدوء مع المعلّم عبر السلالم. لا تستخدم المصعد. وكن منتبهًا، لأن هزّاتٍ أصغر قد تأتي بعده.",image:"media/images/after_earthquake.png"}],examples:["احتمِ تحت طاولةٍ متينة.","ابتعد عن النوافذ.","استمع إلى المعلّم.","اخرج بهدوء بعد الزلزال."],tips:["اعرف الأماكن الآمنة في الصف وفي المنزل.","جهّزوا مع العائلة الماء وحقيبة الطوارئ.","احفظ الرقم 115."],warnings:["أثناء الزلزال لا تركض، ولا تقف تحت الباب، ولا تستخدم المصعد أبدًا!"],realCase:"أثناء أحد الزلازل، احتمى تلميذٌ تحت طاولة وأمسك ساقها، فبقي سالمًا!",video:"media/videos/lesson_earthquake.mp4",game:{instruction:"أيّ هذه التصرفات صحيحة أثناء الزلزال؟",items:[{text:"احتمِ تحت الطاولة",emoji:"🪑",correct:!0},{text:"استخدم المصعد",emoji:"🛗",correct:!1},{text:"احمِ رأسك",emoji:"🛡️",correct:!0},{text:"قف بجانب النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"أنت في الصف والأرض تهتز، والمعلّم ليس موجودًا. ماذا ستفعل؟",image:"media/images/activity_eq.png",options:[{text:"أدخل تحت الطاولة، وأحمي رأسي، وأمسك ساق الطاولة",correct:!0,feedback:"هذا هو «انخفض، احتمِ، تمسّك»، وهو يحميك من الأشياء التي تسقط."},{text:"أركض إلى الخارج",correct:!1,feedback:"قد تسقط وتُصاب إذا ركضت؛ انخفض، واحتمِ، وتمسّك."},{text:"أذهب إلى جانب النافذة",correct:!1,feedback:"زجاج النافذة قد ينكسر ويجرحك؛ ابتعد عن النوافذ."},{text:"أبكي",correct:!1,feedback:"لا بأس أن تخاف، لكن البكاء لا يحميك؛ ادخل تحت الطاولة وأمسك ساقها."}]},quiz:[{question:"ما أول شيء تفعله أثناء الزلزال؟",options:[{text:"انخفض، احتمِ، تمسّك",correct:!0,feedback:"«انخفض، احتمِ، تمسّك» يحميك من الأشياء التي تسقط أثناء الاهتزاز."},{text:"اركض",correct:!1,feedback:"لا، فقد تسقط وتُصاب."},{text:"قف على قدميك",correct:!1,feedback:"لا، فقد تسقط الأشياء عليك."}],explanation:"أثناء الزلزال: انزل على ركبتيك، واحتمِ تحت طاولةٍ متينة، وأمسك ساقها حتى ينتهي الاهتزاز."},{question:"ممّ يجب أن نبتعد؟",options:[{text:"النوافذ والزجاج",correct:!0,feedback:"الزجاج ينكسر ويمكن أن يجرحك، لذلك ابقَ بعيدًا عن النوافذ!"},{text:"الطاولة المتينة",correct:!1,feedback:"لا، الطاولة المتينة مكانٌ آمن."},{text:"أرضية الغرفة",correct:!1,feedback:"لا، أثناء الزلزال يجب أن تنزل إلى الأرض."}],explanation:"الزجاج ينكسر ويمكن أن يجرحك. ابتعد عن النوافذ والمرايا والأشياء الثقيلة التي يمكن أن تسقط."}]},{id:3,icon:"Zap",accent:"#ca8a04",title:"الكهرباء ومخاطرها",subtitle:"السلامة من الكهرباء",grades:"2-3",ages:"7-9",summary:"الكهرباء قوةٌ خفيّة وقويّة. إذا لم نكن حذرين، فقد تؤذينا أو تقتلنا.",blocks:[{heading:"المقابس الكهربائية",body:"لا تُدخل أصابعك أو أيّ أشياء معدنية في المقابس الكهربائية.",image:"media/images/electric_outlet.png"},{heading:"الماء والكهرباء معًا خطر",body:"لا تلمس الأجهزة والمفاتيح الكهربائية بيدين مبلّلتين.",image:"media/images/water_electric.png"},{heading:"الأسلاك المقطوعة",body:"لا تقترب من الأسلاك المقطوعة أو الساقطة، ولا تلمسها. أخبر أحد الكبار فورًا.",image:"media/images/broken_wire.png"}],examples:["لا تلمس المفاتيح بيدين مبلّلتين.","إذا رأيت سلكًا مقطوعًا، فأخبر أحد الكبار.","لا تستخدم الأجهزة المكسورة.","المس المفاتيح بيدين جافّتين فقط."],tips:["أطفئ الأجهزة الكهربائية عندما لا تستخدمها.","لا تستخدم الأجهزة الكهربائية في الحمّام أو بالقرب من الماء.","لا تلمس الأسلاك."],warnings:["لا تلمس الأسلاك المقطوعة الملقاة على الأرض! الكهرباء تقتل!"],realCase:"رأى تلميذٌ سلكًا مقطوعًا في ساحة المدرسة فلم يقترب منه، وأخبر معلّمه فورًا، فبقي جميع التلاميذ سالمين!",video:"media/videos/lesson_electricity.mp4",game:{instruction:"أيّ هذه الأشياء خطِرة؟",items:[{text:"يدان مبلّلتان ومفتاح كهربائي",emoji:"💧",correct:!0},{text:"كتاب",emoji:"📚",correct:!1},{text:"سلك مقطوع",emoji:"⚡",correct:!0},{text:"حذاء",emoji:"👟",correct:!1}]},activity:{prompt:"يداك مبلّلتان وتريد أن تشغّل المروحة. ماذا ستفعل؟",image:"media/images/activity_elec.png",options:[{text:"أجفّف يديّ أولًا",correct:!0,feedback:"اليدان الجافّتان آمنتان، لأن الماء ينقل الكهرباء."},{text:"أشغّلها بيدين مبلّلتين",correct:!1,feedback:"الماء ينقل الكهرباء، لذلك فاليد المبلّلة على المفتاح خطر؛ جفّفها أولًا."},{text:"لا يهمّ",correct:!1,feedback:"بل هو مهمّ: الماء والكهرباء معًا خطر، لذلك جفّف يديك أولًا."},{text:"آخذها إلى الحمّام وأستخدمها هناك",correct:!1,feedback:"الماء ينقل الكهرباء، لذلك لا تستخدم الأجهزة الكهربائية في الحمّام أو قرب الماء."}]},quiz:[{question:"لماذا تكون اليدان المبلّلتان والكهرباء معًا خطرًا؟",options:[{text:"لأن الماء ينقل الكهرباء",correct:!0,feedback:"الماء ينقل الكهرباء، لذلك جفّف يديك أولًا، ثم المس المفتاح."},{text:"لأن اليد تشعر بالحكّة",correct:!1,feedback:"الخطر ليس الحكّة: الماء ينقل الكهرباء، والكهرباء قد تؤذيك."},{text:"لا يهمّ",correct:!1,feedback:"بل هو خطر!"}],explanation:"الماء ينقل الكهرباء. لذلك المس المفاتيح والأجهزة الكهربائية بيدين جافّتين فقط."},{question:"إذا رأيت سلكًا مقطوعًا، فماذا تفعل؟",options:[{text:"لا أقترب منه وأخبر أحد الكبار",correct:!0,feedback:"بابتعادك تبقى آمنًا، وبإخبار أحد الكبار يبقى الجميع آمنين."},{text:"أسحبه",correct:!1,feedback:"هذا خطر!"},{text:"ألمسه",correct:!1,feedback:"لا! الكهرباء تقتل."}],explanation:"الكهرباء تقتل. لا تقترب من الأسلاك المقطوعة أو الساقطة، ولا تلمسها، وأخبر أحد الكبار فورًا."}]},{id:4,icon:"TrafficCone",accent:"#2563eb",title:"السلامة على الطرق",subtitle:"الشارع وحركة المرور",grades:"1-2",ages:"6-8",summary:"الشارع مكانٌ مليء بالمخاطر على الأطفال. هيّا نتعلّم كيف نعبر الطريق بأمان.",blocks:[{heading:"اعبر من ممرّ المشاة",body:"اعبر الطريق دائمًا على الخطوط البيضاء لممرّ المشاة (خطوط الحمار الوحشي).",image:"media/images/crosswalk.png"},{heading:"انظر إلى اليسار واليمين",body:"قف على حافة الطريق. انظر إلى اليسار، ثم إلى اليمين، ثم إلى اليسار مرةً أخرى. وعندما يكون الطريق خاليًا، اعبر بهدوء.",image:"media/images/look_both.png"},{heading:"لغة إشارات المرور",body:"انظر إلى إشارة المشاة، وهي التي فيها صورة شخص صغير. الشخص الأحمر = انتظر على الرصيف. الشخص الأخضر = انظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى، ثم اعبر مباشرة مع شخص كبير. أما الإشارات الكبيرة فهي للسائقين: عندما تكون خضراء تسير السيارات.",image:"media/images/traffic_lights.png"}],examples:["انتبه إلى إشارة المرور.","انظر إلى اليسار واليمين.","اعبر على خطوط المشاة.","أمسك يد أحد الكبار."],tips:["انزع السمّاعات من أذنيك في الشارع.","أمسك يد أحد الكبار عندما تعبر.","كن حذرًا جدًا في الشوارع التي ليس فيها إشارات مرور."],warnings:["لا تعبر أبدًا من بين السيارات المتوقفة!"],realCase:"علّمت تلميذةٌ أصدقاءها كيف يعبرون الطريق بأمان. والآن يذهبون جميعًا إلى المدرسة بسلام!",video:"media/videos/lesson_road.mp4",game:{instruction:"في إشارة المشاة، ماذا يعني الشخص الأخضر؟",items:[{text:"قف",emoji:"🔴",correct:!1},{text:"انظر، ثم اعبر مع شخص كبير",emoji:"🟢",correct:!0},{text:"اركض بسرعة",emoji:"🏃",correct:!1},{text:"اعبر من بين السيارات",emoji:"🚗",correct:!1}]},activity:{prompt:"إشارة المشاة تُظهر الشخص الأحمر، والسيارات قادمة. ماذا ستفعل؟",image:"media/images/activity_road.png",options:[{text:"أنتظر على الرصيف حتى يظهر الشخص الأخضر، ثم أنظر إلى اليسار واليمين ثم اليسار مرة أخرى، وأعبر مع شخص كبير",correct:!0,feedback:"انتظار الشخص الأخضر والنظر مرة أخرى يحميانك من السيارات."},{text:"أركض بسرعة",correct:!1,feedback:"السيارات قادمة والإشارة حمراء؛ الركض ليس آمنًا، لذلك انتظر على الرصيف."},{text:"أعبر دون أن أنظر",correct:!1,feedback:"إذا لم تنظر فلن ترى السيارات؛ انتظر الشخص الأخضر، وانظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى."},{text:"أعبر من بين السيارات",correct:!1,feedback:"العبور من بين السيارات ليس آمنًا؛ اعبر على خطوط المشاة البيضاء عندما يظهر الشخص الأخضر."}]},quiz:[{question:"ماذا يعني الضوء الأحمر؟",options:[{text:"قف",correct:!0,feedback:"الأحمر يعني «قف»، لذلك انتظر بأمان على الرصيف."},{text:"امشِ",correct:!1,feedback:"الأحمر ليس للمشي: انتظر على الرصيف حتى يظهر الشخص الأخضر."},{text:"اركض بسرعة",correct:!1,feedback:"الركض والإشارة حمراء ليس آمنًا؛ قف وانتظر على الرصيف."}],explanation:"الأحمر يعني «قف»: عندما يظهر الشخص الأحمر، انتظر على الرصيف. وعندما يظهر الشخص الأخضر، انظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى، واعبر مع شخص كبير."},{question:"ماذا تفعل قبل أن تعبر الطريق؟",options:[{text:"أنظر إلى اليسار واليمين",correct:!0,feedback:"النظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى يُريك هل الطريق خالٍ أم لا."},{text:"أركض",correct:!1,feedback:"الركض إلى الطريق ليس آمنًا؛ قف أولًا على الحافة وانظر إلى اليسار واليمين."},{text:"لا أفعل شيئًا",correct:!1,feedback:"قبل العبور، قف دائمًا وانظر إلى اليسار واليمين لتعرف أن الطريق خالٍ."}],explanation:"قف على حافة الطريق، وانظر إلى اليسار، ثم إلى اليمين، ثم إلى اليسار مرةً أخرى. ولا تعبر إلا عندما يكون الطريق خاليًا، وبهدوء."}]},{id:5,icon:"HeartPulse",accent:"#16a34a",title:"الإسعافات الأولية",subtitle:"أساسيات الإسعافات الأولية",grades:"3-4",ages:"8-10",summary:"الإسعافات الأولية هي مساعدةٌ فورية لشخصٍ مصاب أو مريض قبل أن تصل سيارة الإسعاف. إذا كانت إصابة شخصٍ ما أو مرضه خطيرًا، فأخبر أحد الكبار ليتصل بالرقم 122 (الإسعاف).",blocks:[{heading:"الجروح الصغيرة",body:"اغسل الجرح بماءٍ نظيف، وضع عليه ضمادةً نظيفة، وأخبر أحد الكبار.",image:"media/images/first_aid_wound.png"},{heading:"الحروق",body:"ضع مكان الحرق تحت ماءٍ جارٍ بارد لمدة 20 دقيقة. لا تضع عليه ثلجًا أو زبدةً أو معجون أسنان. أخبر أحد الكبار؛ ففي الحروق الشديدة يتصلون بالرقم 122.",image:"media/images/first_aid_burn.png"},{heading:"صندوق الإسعافات الأولية",body:"يجب أن يكون في كل منزلٍ ومدرسة صندوقٌ للإسعافات الأولية.",image:"media/images/first_aid_kit.png"}],examples:["استخدم ضمادةً نظيفة.","للحرق: ماءٌ بارد لمدة 20 دقيقة.","الإسعاف = 122؛ أخبر أحد الكبار.","اعرف مكان صندوق الإسعافات الأولية."],tips:["اغسل يديك قبل وضع الضمادة.","لا تلمس داخل الجرح بيدك.","تحدّث مع المصاب بهدوء."],warnings:["لا تعطِ أحدًا أدويةً من تلقاء نفسك أبدًا! قدّم المساعدة البسيطة فقط، وأخبر الكبار."],realCase:"سقط تلميذٌ في الساحة فجُرحت ركبته. فأخبر أحد أصدقائه المعلّمَ فورًا، فنظّف المعلّم الجرح وضمّده، وسرعان ما شُفي!",video:"media/videos/lesson_firstaid.mp4",game:{instruction:"ماذا يوجد في صندوق الإسعافات الأولية؟",items:[{text:"ضمادة",emoji:"🩹",correct:!0},{text:"حلوى",emoji:"🍬",correct:!1},{text:"قطن",emoji:"🩹",correct:!0},{text:"دمية",emoji:"🧸",correct:!1}]},activity:{prompt:"سقط صديقك والدم يسيل من يده. ماذا ستفعل؟",image:"media/images/activity_fa.png",options:[{text:"أضغط على الجرح بمنديلٍ نظيف، وأخبر المعلّم فورًا",correct:!0,feedback:"المنديل النظيف على الجرح يساعد، وبإخبار المعلّم يحصل صديقك على المساعدة بسرعة."},{text:"لا أفعل شيئًا",correct:!1,feedback:"صديقك يحتاج إلى المساعدة؛ اضغط على الجرح بمنديلٍ نظيف وأخبر المعلّم فورًا."},{text:"أركض وأبتعد",correct:!1,feedback:"إذا ركضت بعيدًا بقي صديقك بلا مساعدة؛ أخبر المعلّم فورًا."},{text:"أتابع لعبي",correct:!1,feedback:"صديقك مصاب ويحتاج إلى المساعدة الآن؛ توقّف عن اللعب وأخبر المعلّم فورًا."}]},quiz:[{question:"ماذا نفعل لحرقٍ صغير؟",options:[{text:"ماءٌ جارٍ بارد لمدة 20 دقيقة",correct:!0,feedback:"الماء الجاري البارد لمدة 20 دقيقة يبرّد الحرق؛ ثم أخبر أحد الكبار."},{text:"بهارات",correct:!1,feedback:"للحرق استخدم ماءً جاريًا باردًا لمدة 20 دقيقة، لا البهارات."},{text:"زبدة",correct:!1,feedback:"لا! الزبدة تجعل الحرق أسوأ."}],explanation:"ضع مكان الحرق تحت ماءٍ جارٍ بارد لمدة 20 دقيقة. لا تضع عليه ثلجًا أو زبدةً أو معجون أسنان، وأخبر أحد الكبار."},{question:"ماذا نفعل بأيدينا قبل وضع الضمادة؟",options:[{text:"نغسلها",correct:!0,feedback:"اليدان النظيفتان تساعدان على بقاء الجرح نظيفًا."},{text:"لا نفعل شيئًا",correct:!1,feedback:"اغسل يديك أولًا، لكي يبقى الجرح نظيفًا."},{text:"ننظّفها بملابسنا",correct:!1,feedback:"مسح اليدين بالملابس ليس غسلًا؛ اغسل يديك قبل وضع الضمادة."}],explanation:"اغسل يديك قبل وضع الضمادة، لكي يبقى الجرح نظيفًا. ولا تلمس داخل الجرح."}]},{id:6,icon:"Waves",accent:"#0891b2",title:"الفيضان والسلامة من المياه",subtitle:"خطر الفيضانات",grades:"2-3",ages:"7-9",summary:"يحدث الفيضان عندما يهطل المطر بغزارة وتتجمّع المياه. الفيضان خطير، ويمكن أن يجرف معه الأشياء والناس.",blocks:[{heading:"ابتعد عن مياه الفيضان",body:"لا تدخل أبدًا في مياه الفيضان. فالماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان، وبعمق 30 سنتيمترًا يمكن أن يجرف سيارة.",image:"media/images/flood_danger.png"},{heading:"اذهب إلى مكانٍ مرتفع",body:"إذا جاء الفيضان، فاذهبوا فورًا مع الكبار إلى مكانٍ مرتفع.",image:"media/images/flood_high.png"},{heading:"تحذيرات الطقس",body:"استمع إلى تحذيرات الطقس وإلى إرشادات الكبار، وكن مستعدًا.",image:"media/images/flood_warning.png"}],examples:["إذا كان منزلك في مكانٍ مرتفع، فابقَ في المنزل.","اذهب إلى مكانٍ مرتفع.","استمع إلى التحذيرات.","لا تلعب في مياه الفيضان."],tips:["عندما يأتي الفيضان، لا تذهب إلى الأماكن المنخفضة والوديان.","أخبر الكبار.","استعدّ قبل موسم الأمطار."],warnings:["لا تدخل أبدًا في مياه الفيضان ولا تسبح فيها! فمياه الفيضان أقوى منك."],realCase:"أثناء مطرٍ غزير جدًا، دخل الماء إلى الشارع. فأخذ أبٌ أطفاله إلى الطابق الثالث من المبنى، وبقي الجميع سالمين!",video:"media/videos/lesson_flood.mp4",game:{instruction:"ماذا نفعل أثناء الفيضان؟",items:[{text:"اذهب إلى مكانٍ مرتفع",emoji:"⬆️",correct:!0},{text:"اسبح في الماء",emoji:"🏊",correct:!1},{text:"ابقَ في الطابق العلوي من المنزل",emoji:"🏠",correct:!0},{text:"اعبر الماء بالسيارة",emoji:"🚗",correct:!1}]},activity:{prompt:"المطر يهطل بغزارة والماء يتجمّع في الشارع. ماذا ستفعل؟",image:"media/images/activity_flood.png",options:[{text:"أذهب مع الكبار إلى مكانٍ مرتفع",correct:!0,feedback:"الذهاب مع الكبار إلى مكانٍ مرتفع يُبقيك بعيدًا عن مياه الفيضان."},{text:"أمشي في الماء",correct:!1,feedback:"الماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان؛ لا تمشِ أبدًا في مياه الفيضان."},{text:"أقف بالقرب من الماء وأتفرّج",correct:!1,feedback:"الفيضان يمكن أن يجرف الناس، فلا تبقَ قرب الماء؛ اذهب مع الكبار إلى مكانٍ مرتفع."},{text:"أسبح",correct:!1,feedback:"مياه الفيضان أقوى منك حتى لو كنت تعرف السباحة؛ اذهب مع الكبار إلى مكانٍ مرتفع."}]},quiz:[{question:"إذا جاء الفيضان، فإلى أين نذهب؟",options:[{text:"إلى مكانٍ مرتفع",correct:!0,feedback:"المكان المرتفع يُبقيك بعيدًا عن مياه الفيضان."},{text:"إلى الأماكن المنخفضة",correct:!1,feedback:"الأماكن المنخفضة والوديان ليست آمنة أثناء الفيضان؛ اذهب مع الكبار إلى مكانٍ مرتفع."},{text:"إلى داخل الماء",correct:!1,feedback:"مياه الفيضان أقوى منك ويمكن أن تجرفك؛ لا تدخل فيها أبدًا."}],explanation:"مياه الفيضان أقوى منك: فالماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان. اذهب فورًا مع الكبار إلى مكانٍ مرتفع."}]},{id:7,icon:"Wind",accent:"#059669",title:"تسرّب الغاز",subtitle:"كيف نعرف خطر الغاز",grades:"3-4",ages:"8-10",summary:"يُستخدم الغاز للطبخ ولتدفئة المنزل. تسرّب الغاز خطير، وقد يسبّب حريقًا أو انفجارًا.",blocks:[{heading:"رائحة الغاز",body:"إذا شممت رائحةً تشبه رائحة البيض الفاسد، فربما يكون الغاز قد تسرّب!",image:"media/images/gas_smell.png"},{heading:"افتح النوافذ",body:"إذا استطعت ذلك بسهولة في طريقك إلى الخارج، فافتح النوافذ والأبواب ليخرج الغاز. ولا تبقَ في الداخل من أجل ذلك: اخرج من المنزل فورًا.",image:"media/images/gas_ventilate.png"},{heading:"لا تُشعل النار!",body:"لا تُشعل عود ثقاب أو ولّاعة، ولا تلمس مفاتيح الكهرباء، ولا تستخدم الهاتف داخل المنزل. فحتى الشرارة الصغيرة يمكن أن تسبّب انفجارًا.",image:"media/images/gas_no_fire.png"}],examples:["رائحة البيض الفاسد = غاز.","افتح النوافذ.","لا تُشعل النار!","اخرجوا، واتصلوا بالرقم 115 من الخارج."],tips:["الأطفال لا يُغلقون الغاز أبدًا: اخرج وأخبر أحد الكبار.","يجب على الكبار أن يفحصوا أنابيب الغاز باستمرار.","اتصلوا بالرقم 115 من خارج المنزل."],warnings:["عندما تشمّ رائحة الغاز، لا تلمس مفاتيح الكهرباء ولا تُشعل النار!"],realCase:"شمّ طفلٌ رائحة الغاز في المطبخ، فلم يلمس المفاتيح، وأخبر والده. فخرج الجميع من المنزل، واتصل الأب بالرقم 115 من الخارج، وبقي الجميع سالمين!",video:"media/videos/lesson_gas.mp4",game:{instruction:"عند شمّ رائحة الغاز، أيّ هذه الأفعال لا يجوز أن نفعلها؟",items:[{text:"نُشعل عود ثقاب",emoji:"🔥",correct:!0},{text:"نفتح النافذة",emoji:"🪟",correct:!1},{text:"نُشغّل مفتاح الكهرباء",emoji:"💡",correct:!0},{text:"نخرج من المنزل",emoji:"🚶",correct:!1}]},activity:{prompt:"في المنزل رائحةٌ تشبه رائحة البيض الفاسد. ماذا ستفعل؟",image:"media/images/activity_gas.png",options:[{text:"لا ألمس المفاتيح، وأخرج وأفتح نافذة في طريقي إن كان ذلك سهلًا، وأخبر أحد الكبار",correct:!0,feedback:"بعدم لمس المفاتيح لا تحدث شرارة، وبالخروج وإخبار أحد الكبار يبقى الجميع آمنين."},{text:"أُشعل المصباح لأرى جيدًا",correct:!1,feedback:"المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا؛ لا تلمس المفاتيح."},{text:"أبقى في المنزل",correct:!1,feedback:"الغاز قد يسبّب حريقًا أو انفجارًا، لذلك اخرج من المنزل فورًا وأخبر أحد الكبار."},{text:"أُشعل عود ثقاب",correct:!1,feedback:"عود الثقاب قد يسبّب انفجارًا؛ لا تُشعل النار أبدًا، واخرج وأخبر أحد الكبار."}]},quiz:[{question:"كيف تكون رائحة الغاز؟",options:[{text:"مثل البيض الفاسد",correct:!0,feedback:"رائحةٌ تشبه البيض الفاسد تنبّهك إلى أن الغاز ربما تسرّب."},{text:"مثل الورد",correct:!1,feedback:"رائحة الغاز ليست مثل الورد؛ بل تشبه البيض الفاسد لكي تنتبه إليها."},{text:"ليست له رائحة",correct:!1,feedback:"لا! تُضاف إلى الغاز رائحةٌ لكي نعرف بوجوده."}],explanation:"رائحة الغاز تشبه رائحة البيض الفاسد، لأن رائحةً تُضاف إليه لكي نعرف بوجوده. إذا شممتها، فلا تلمس المفاتيح، واخرج وأخبر أحد الكبار."}]},{id:8,icon:"PhoneCall",accent:"#e11d48",title:"رقم الطوارئ 115",subtitle:"الاتصال لطلب المساعدة",grades:"1-2",ages:"6-8",summary:"الرقم 115 هو رقم الدفاع المدني: للحرائق، والإنقاذ، والزلازل، والفيضانات، وتسرّب الغاز. في حالات الطوارئ، أخبر أحد الكبار ليتصل بالرقم 115. وإذا لم يكن بالقرب منك أحدٌ من الكبار، فاتصل أنت بنفسك.",blocks:[{heading:"115 = الدفاع المدني",body:"الحريق، الزلزال، الفيضان، الانفجار، انهيار المباني = اتصل بالرقم 115",image:"media/images/call_115.png"},{heading:"ماذا أقول؟",body:"قل أولًا أين أنت (عنوان المكان أو مكانًا قريبًا منك). ثم قل ما الذي حدث، وكم شخصًا هناك، وهل يوجد مصابون، واذكر اسمك. لا تُغلق الهاتف حتى يطلبوا منك ذلك.",image:"media/images/what_to_say.png"},{heading:"لا تمزح",body:"لا تتصل بالرقم 115 للّعب أبدًا! فقد يكون شخصٌ آخر بحاجةٍ إلى المساعدة.",image:"media/images/no_prank.png"}],examples:["115 = الدفاع المدني.","122 = الإسعاف.","104 = الشرطة.","احفظ هذه الأرقام."],tips:["احفظ عنوان منزلك.","تحدّث بهدوء.","استمع إلى التعليمات."],warnings:["لا تتصل بالرقم 115 للّعب! فهذا تصرّفٌ خاطئ وممنوع."],realCase:"رأى طفلٌ عمره 10 سنوات نارًا بالقرب من منزله، فأخبر أمّه فورًا، فاتصلت أمّه بالرقم 115، وجاء فريق الدفاع المدني بسرعة!",video:"media/videos/lesson_115.mp4",game:{instruction:"الرقم 115 لِمَن؟",items:[{text:"الدفاع المدني",emoji:"🚒",correct:!0},{text:"الشرطة",emoji:"👮",correct:!1},{text:"الإسعاف",emoji:"🏥",correct:!1},{text:"فريق الإطفاء",emoji:"🧯",correct:!0}]},activity:{prompt:"هناك نارٌ بالقرب من المنزل، ولا يوجد أحدٌ من الكبار معك. ماذا ستفعل؟",image:"media/images/activity_115.png",options:[{text:"أبتعد عن النار، وأتصل بالرقم 115، وأذكر عنوان المكان",correct:!0,feedback:"الابتعاد عن النار يحميك، وبذكر عنوان المكان يصل الفريق بسرعة."},{text:"أطفئ النار بنفسي",correct:!1,feedback:"الأطفال لا يُطفئون النار؛ ابتعد، واتصل بالرقم 115، واذكر عنوان المكان."},{text:"أبقى قريبًا وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ ابتعد واتصل بالرقم 115."},{text:"أدخل إلى المنزل",correct:!1,feedback:"دخول المنزل يعرّضك للخطر؛ ابقَ في الخارج، وابتعد، واتصل بالرقم 115."}]},quiz:[{question:"لِمَن الرقم 115؟",options:[{text:"الدفاع المدني",correct:!0,feedback:"الرقم 115 للدفاع المدني: الحرائق والإنقاذ والزلازل والفيضانات وتسرّب الغاز."},{text:"الشرطة",correct:!1,feedback:"لا، رقم الشرطة هو 104."},{text:"الإسعاف",correct:!1,feedback:"لا، رقم الإسعاف هو 122."}],explanation:"الرقم 115 هو رقم الدفاع المدني: للحرائق والإنقاذ والزلازل والفيضانات وتسرّب الغاز. أمّا رقم الشرطة فهو 104، ورقم الإسعاف 122."}]},{id:9,icon:"DoorOpen",accent:"#7c3aed",title:"خطة الإخلاء",subtitle:"الخروج الآمن",grades:"3-4",ages:"8-10",summary:"تحدّد خطة الإخلاء الطريق الذي نخرج منه من المبنى بأمان، والمكان الذي نتجمّع فيه.",blocks:[{heading:"طرق الخروج",body:"يجب أن يكون في كل منزلٍ ومدرسة طريقان للخروج على الأقل.",image:"media/images/exit_routes.png"},{heading:"نقطة التجمع",body:"هي مكانٌ آمن خارج المبنى، يتجمّع فيه الجميع ليتأكّدوا أنه لم يبقَ أحدٌ في الداخل.",image:"media/images/assembly_point.png"},{heading:"التدريب",body:"تدرّبوا على الإخلاء في المنزل وفي المدرسة مرةً كل ثلاثة أشهر.",image:"media/images/evacuation_drill.png"}],examples:["اعرف طريقين للخروج.","اعرف نقطة التجمع.","اخرج بهدوء.","ارسم خريطة الإخلاء."],tips:["ارسم مع عائلتك خريطة المنزل.","اعرف طرق الخروج جيدًا، بحيث تستطيع الخروج حتى في الظلام.","حدّد نقطة التجمع."],warnings:["أثناء الحريق أو الزلزال لا تستخدم المصعد، بل استخدم السلالم!"],realCase:"خرج تلاميذ إحدى المدارس بسرعة وأمان، لأنهم كانوا قد تدرّبوا على ذلك من قبل!",video:"media/videos/lesson_evacuation.mp4",game:{instruction:"ماذا نستخدم للخروج الآمن؟",items:[{text:"السلالم",emoji:"🪜",correct:!0},{text:"المصعد",emoji:"🛗",correct:!1},{text:"باب مخرج الطوارئ",emoji:"🚪",correct:!0},{text:"النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"رنّ جرس الإنذار في المدرسة. ماذا ستفعل؟",image:"media/images/activity_evac.png",options:[{text:"أذهب بهدوء عبر السلالم إلى نقطة التجمع",correct:!0,feedback:"النزول بهدوء عبر السلالم آمن، وفي نقطة التجمع نتأكّد أنه لم يبقَ أحدٌ في الداخل."},{text:"أجمع أغراضي",correct:!1,feedback:"الخروج هو أول شيء، لذلك اترك أغراضك واذهب بهدوء إلى نقطة التجمع."},{text:"أنزل بالمصعد",correct:!1,feedback:"قد يتوقّف المصعد وتبقى عالقًا فيه؛ استخدم السلالم."},{text:"أختبئ",correct:!1,feedback:"إذا اختبأت فلن يعرف أحد أنك ما زلت في الداخل؛ اذهب إلى نقطة التجمع."}]},quiz:[{question:"ماذا نستخدم لنخرج من المبنى بأمان؟",options:[{text:"السلالم",correct:!0,feedback:"السلالم هي الطريق الآمن، لأن المصعد قد يتوقّف أثناء الحريق أو الزلزال."},{text:"المصعد",correct:!1,feedback:"لا! فقد يتوقّف المصعد وتبقى عالقًا فيه."},{text:"النافذة",correct:!1,feedback:"طريق الخروج الآمن هو السلالم وباب مخرج الطوارئ، لا النافذة."}],explanation:"أثناء الحريق أو الزلزال استخدم السلالم، لا المصعد. فقد يتوقّف المصعد وتبقى عالقًا فيه."}]},{id:10,icon:"FireExtinguisher",accent:"#d97706",title:"معدّات إطفاء الحريق",subtitle:"مطفأة الحريق والأدوات الأخرى",grades:"4-5",ages:"9-11",summary:"مطفأة الحريق (Fire Extinguisher) جهازٌ مهم لإطفاء الحرائق الصغيرة، ويستخدمها الكبار المدرَّبون. أمّا دور الأطفال فهو أن يخرجوا، ويُخبروا أحد الكبار ليتمّ الاتصال بالرقم 115.",blocks:[{heading:"أنواع مطافئ الحريق",body:"هناك مطفأة المسحوق، ومطفأة ثاني أكسيد الكربون (CO₂)، ومطفأة الرغوة. وكل نوعٍ منها مخصّص لأنواعٍ معيّنة من الحرائق.",image:"media/images/ext_types.png"},{heading:"P.A.S.S",body:`الكبار هم من يقرّرون استخدام مطفأة الحريق. ولا يستخدمونها إلا إذا كانت النار صغيرة جدًا وفي بدايتها، ونُبِّه الجميع واتُّصل بالرقم 115، وكان طريق الخروج خلفهم وخاليًا من الدخان، وكانوا مدرَّبين. وإلّا يخرج الجميع. والأطفال لا يستخدمون المطفأة أبدًا: اخرج، وأخبر أحد الكبار، واتصل بالرقم 115.

يستخدم الكبار معظم مطافئ الحريق بهذه الخطوات الأربع: Pull (اسحب مسمار الأمان)، Aim (وجّه فوهة الخرطوم إلى قاعدة النار)، Squeeze (اضغط على المقبض)، Sweep (حرّكها من جانبٍ إلى آخر). ولبعض المطافئ الخاصة خطوات أخرى مكتوبة على ملصقها.`,image:"media/images/pass_method.png"},{heading:"للحرائق الصغيرة فقط",body:"مطفأة الحريق مخصّصة للحرائق الصغيرة جدًا فقط، ويستخدمها الكبار. الأطفال لا يُطفئون النار: اخرج، وأخبر أحد الكبار، واتصلوا بالرقم 115!",image:"media/images/when_use_ext.png"}],examples:["P = Pull: اسحب المسمار.","A = Aim: وجّهها إلى قاعدة النار.","S = Squeeze: اضغط على المقبض.","S = Sweep: حرّكها من جانبٍ إلى آخر."],tips:["يفحص الكبار مطفأة الحريق بالنظر كل شهر، ويأخذونها للصيانة كل سنة.","اعرف أماكن مطافئ الحريق في المدرسة.","أثناء الحريق، نادِ الكبار."],warnings:["الأطفال لا يُطفئون النار! مطفأة الحريق للكبار. أمّا أنت فاخرج، وأخبر أحد الكبار، واتصل بالرقم 115."],realCase:"اشتعلت نارٌ صغيرة في سلّة المهملات في أحد الصفوف. فخرج التلاميذ فورًا، وأخبر أحدهم المعلّم، وكان المعلّم مدرَّبًا، فتأكّد من إطلاق الإنذار والاتصال بالرقم 115. وكانت النار لا تزال صغيرة جدًا وطريق الخروج خلفه، فأطفأها بمطفأة الحريق مستخدمًا طريقة P.A.S.S.",video:"media/videos/lesson_extinguisher.mp4",game:{instruction:"ماذا تعني P.A.S.S؟",items:[{text:"خطوات استخدام مطفأة الحريق",emoji:"🧯",correct:!0},{text:"نوعٌ من الحرائق",emoji:"🔥",correct:!1},{text:"رقم الطوارئ",emoji:"📞",correct:!1},{text:"اسحب، وجّهها إلى قاعدة النار، اضغط، حرّك",emoji:"✅",correct:!0}]},activity:{prompt:"هناك نارٌ صغيرة في سلّة المهملات في الصف، ومطفأة الحريق قريبةٌ منك. ماذا ستفعل؟",image:"media/images/activity_ext.png",options:[{text:"أخرج من الصف فورًا، وأخبر المعلّم، ونتصل بالرقم 115",correct:!0,feedback:"الخروج وإخبار المعلّم والاتصال بالرقم 115 هو دور الأطفال، لا إطفاء النار."},{text:"أسكب الماء على النار",correct:!1,feedback:"الأطفال لا يُطفئون النار، حتى الصغيرة منها؛ اخرج من الصف وأخبر المعلّم."},{text:"أستخدم مطفأة الحريق بنفسي",correct:!1,feedback:"مطفأة الحريق للكبار المدرَّبين؛ أمّا الأطفال فيخرجون، ويُخبرون أحد الكبار، ويتصلون بالرقم 115."},{text:"أبقى في الصف وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ اخرج من الصف فورًا وأخبر المعلّم."}]},quiz:[{question:"ماذا يعني الحرف P في P.A.S.S؟",options:[{text:"Pull: اسحب المسمار",correct:!0,feedback:"الخطوة الأولى هي أن يسحب الشخص الكبير مسمار الأمان (Pull)."},{text:"Push: ادفع",correct:!1,feedback:"لا توجد خطوة Push: الحرف P يعني Pull، أي سحب مسمار الأمان."},{text:"Pour: اسكب",correct:!1,feedback:"لا توجد خطوة Pour: الحرف P يعني Pull، أي سحب مسمار الأمان."}],explanation:"الحرف P يعني Pull: اسحب مسمار الأمان. لكنّ الكبار المدرَّبين وحدهم يستخدمون مطفأة الحريق؛ أمّا الأطفال فيخرجون، ويُخبرون أحد الكبار، ويتصلون بالرقم 115."}]},{id:11,icon:"CloudFog",accent:"#475569",title:"الدخان والتنفّس",subtitle:"تنفّس الهواء النقي",grades:"2-3",ages:"7-9",summary:"الدخان خطيرٌ جدًا. فهو يجعل التنفّس صعبًا، ويمنعك من أن ترى جيدًا.",blocks:[{heading:"الدخان يرتفع إلى الأعلى",body:"الهواء النقي يكون قريبًا من الأرض. فانخفض وازحف على يديك وركبتيك حتى تخرج.",image:"media/images/smoke_rises.png"},{heading:"منديلٌ مبلّل",body:"إذا كان معك منديلٌ مبلّل، فضعه على فمك وأنفك. ولكن لا تتوقّف للبحث عنه، بل اخرج فورًا.",image:"media/images/wet_cloth.png"},{heading:"افحص الباب",body:"قبل أن تفتح الباب، المسه بظهر يدك. فإذا كان ساخنًا، فلا تفتحه وابحث عن طريقٍ آخر. وبعد أن تخرج، أغلق الباب خلفك.",image:"media/images/check_door.png"}],examples:["انخفض.","ضع منديلًا مبلّلًا على فمك.","افحص الباب بظهر يدك.","ازحف على ركبتيك واخرج."],tips:["ركّبوا جهاز إنذار الدخان في المنزل.","اعرف طريق الخروج حتى في الظلام.","الهواء النقي يكون في الأسفل."],warnings:["في الحرائق، يقتل الدخانُ الناسَ أكثر ممّا تقتلهم النار نفسها! لا تستخدم المصعد."],realCase:"أثناء حريقٍ في أحد المنازل، انخفض طفلٌ عمره 10 سنوات وخرج من المنزل زاحفًا. وهذه المعرفة يمكن أن تنقذ حياتك أنت أيضًا!",video:"media/videos/lesson_smoke.mp4",game:{instruction:"ماذا نفعل عند وجود الدخان؟",items:[{text:"انخفض",emoji:"🐢",correct:!0},{text:"امشِ واقفًا على قدميك",emoji:"🧍",correct:!1},{text:"منديلٌ مبلّل",emoji:"🧣",correct:!0},{text:"افتح النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"امتلأت الغرفة بالدخان ولا تستطيع أن ترى جيدًا. ماذا ستفعل؟",image:"media/images/activity_smoke.png",options:[{text:"أنخفض، وأضع منديلًا على فمي، وأخرج زاحفًا",correct:!0,feedback:"الهواء في الأسفل أنقى، والزحف يُخرجك من الدخان."},{text:"أمشي بسرعة واقفًا على قدميّ",correct:!1,feedback:"عندما تقف يكون رأسك داخل الدخان؛ انخفض واخرج زاحفًا."},{text:"أفتح النافذة وأبقى هناك",correct:!1,feedback:"البقاء في غرفة مليئة بالدخان خطر؛ انخفض واخرج من الغرفة زاحفًا."},{text:"أبقى في الغرفة",correct:!1,feedback:"الدخان يجعل التنفّس صعبًا، فلا تبقَ؛ انخفض واخرج زاحفًا."}]},quiz:[{question:"لماذا ننخفض عند وجود الدخان؟",options:[{text:"لأن الدخان يرتفع إلى الأعلى، والهواء النقي يكون في الأسفل",correct:!0,feedback:"الدخان يرتفع والهواء النقي يبقى في الأسفل، لذلك يحميك الانخفاض."},{text:"لأن ذلك ممتع",correct:!1,feedback:"الانخفاض ليس لعبة: فهو يُبقيك في الهواء النقي تحت الدخان."},{text:"لكي نرى بشكلٍ أفضل",correct:!1,feedback:"ننخفض لكي نتنفّس: فالدخان يرتفع، والهواء النقي يكون قريبًا من الأرض."}],explanation:"الدخان يرتفع إلى الأعلى، لذلك يكون الهواء النقي قريبًا من الأرض. انخفض وازحف على يديك وركبتيك حتى تخرج."}]},{id:12,icon:"FlaskConical",accent:"#9333ea",title:"المواد الكيميائية",subtitle:"خطر المواد المجهولة",grades:"4-5",ages:"9-11",summary:"توجد في المنازل موادّ كيميائية، مثل موادّ التنظيف والبنزين. وهذه الموادّ خطيرة إذا استُخدمت بطريقةٍ خاطئة.",blocks:[{heading:"لا تشربها ولا تلمسها",body:"لا تشرب سائلًا مجهولًا ولا تشمّه، فقد يكون سامًّا.",image:"media/images/chem_no_drink.png"},{heading:"رموز الخطر",body:"تعرّف على رموز الخطر الموجودة على الزجاجات والعلب. إذا وجدت رمزًا منها على شيء، فلا تلمسه وأخبر أحد الكبار.",image:"media/images/chem_signs.png"},{heading:"إذا دخلت في العينين",body:"أخبر أحد الكبار فورًا. اغسلوا العينين بماءٍ نظيف جارٍ لمدة 15 دقيقة على الأقل، واتصلوا بالرقم 122 (الإسعاف).",image:"media/images/chem_eye.png"}],examples:["لا تشرب سائلًا مجهولًا.","تعرّف على رموز الخطر.","إذا دخلت في العينين: اغسلهما بالماء.","التسمّم: اتصل بالرقم 122."],tips:["يجب على الكبار أن يضعوا الموادّ الخطيرة في مكانٍ مرتفع ومُغلق.","تعرّف على الرموز.","أخبر الكبار."],warnings:["لا تخلط موادّ التنظيف بعضها ببعض أبدًا! فقد يتكوّن غازٌ سام."],realCase:"رأت طفلةٌ زجاجةً ملوّنة في المطبخ، فلم تشرب منها، بل سألت أمّها، فعرفت أنها مادة تنظيفٍ خطيرة.",video:"media/videos/lesson_chemical.mp4",game:{instruction:"أيّ هذه الأشياء خطِرة؟",items:[{text:"موادّ التنظيف",emoji:"🧴",correct:!0},{text:"الماء",emoji:"💧",correct:!1},{text:"البنزين",emoji:"⛽",correct:!0},{text:"الحليب",emoji:"🥛",correct:!1}]},activity:{prompt:"وجدت في الحمّام زجاجةً فيها سائلٌ مجهول. ماذا ستفعل؟",image:"media/images/activity_chem.png",options:[{text:"لا ألمسها، وأخبر أحد الكبار",correct:!0,feedback:"السائل المجهول قد يكون سامًّا، لذلك تبقى آمنًا إذا لم تلمسه وأخبرت أحد الكبار."},{text:"أشمّها",correct:!1,feedback:"حتى شمّ السائل المجهول خطر، لأنه قد يكون سامًّا؛ أخبر أحد الكبار."},{text:"أسكب منها على يديّ",correct:!1,feedback:"السائل المجهول قد يكون سامًّا، فلا تلمسه؛ أخبر أحد الكبار."},{text:"أشرب منها",correct:!1,feedback:"السائل المجهول قد يكون سامًّا، فلا تشرب منه أبدًا؛ أخبر أحد الكبار فورًا."}]},quiz:[{question:"إذا دخلت مادةٌ كيميائية في عينيك، فماذا تفعل؟",options:[{text:"أغسلهما بماءٍ نظيف لمدة 15 دقيقة على الأقل، وأخبر أحد الكبار",correct:!0,feedback:"الغسل بالماء النظيف لمدة 15 دقيقة على الأقل يُزيل المادة من العينين، ويستطيع الشخص الكبير الاتصال بالرقم 122."},{text:"أفرك عينيّ بيديّ",correct:!1,feedback:"لا! فهذا يزيد الضرر."},{text:"لا أفعل شيئًا",correct:!1,feedback:"المادة الكيميائية في العين تحتاج إلى مساعدةٍ فورية: اغسلها بماءٍ نظيف وأخبر أحد الكبار."}],explanation:"اغسل عينيك بماءٍ نظيف جارٍ لمدة 15 دقيقة على الأقل، وأخبر أحد الكبار فورًا ليتصل بالرقم 122 (الإسعاف)."}]},{id:13,icon:"AlertTriangle",accent:"#db2777",title:"إشارات السلامة",subtitle:"التعرّف على الإشارات والعلامات",grades:"1-2",ages:"6-8",summary:"إشارات السلامة تخبرنا من دون كلام: هنا يوجد خطر، أو هذا الفعل ممنوع، أو هذا هو طريق الخروج.",blocks:[{heading:"المثلث الأصفر = خطر",body:"المثلث الأصفر الذي فيه صورةٌ سوداء معناه: انتبه، يوجد خطر!",image:"media/images/warning_sign.png"},{heading:"الدائرة الحمراء = ممنوع",body:"الدائرة الحمراء التي يقطعها خطٌّ أحمر معناها: لا تفعل هذا!",image:"media/images/prohibit_sign.png"},{heading:"الأخضر = السلامة",body:"المربّع الأخضر معناه السلامة، مثل طريق مخرج الطوارئ أو مكان الإسعافات الأولية.",image:"media/images/exit_sign.png"}],examples:["المثلث الأصفر = خطر.","الدائرة الحمراء = ممنوع.","المربّع الأخضر = سلامة.","الدائرة الزرقاء = إلزامي (يجب أن تفعله)."],tips:["تعلّم ألوان الإشارات.","ابحث عن الإشارات في المدرسة.","تعرّف على إشارة مخرج الطوارئ."],warnings:["اقرأ الإشارات والتزم بها!"],realCase:"رأت طفلةٌ إشارة خطر الكهرباء على أحد الأبواب، فابتعدت عنه. فقال لها المعلّم: أحسنتِ!",video:"media/videos/lesson_signs.mp4",game:{instruction:"ماذا يعني المثلث الأصفر؟",items:[{text:"خطر!",emoji:"⚠️",correct:!0},{text:"امشِ!",emoji:"🟢",correct:!1},{text:"ممنوع",emoji:"🚫",correct:!1},{text:"انتبه",emoji:"👀",correct:!0}]},activity:{prompt:"ترى إشارةً خضراء فيها سهمٌ أبيض. ماذا تعني؟",image:"media/images/activity_signs.png",options:[{text:"طريق الخروج الآمن",correct:!0,feedback:"الأخضر معناه السلامة، والسهم يدلّ على طريق مخرج الطوارئ."},{text:"ممنوع",correct:!1,feedback:"«ممنوع» تدلّ عليه الدائرة الحمراء التي يقطعها خط؛ أمّا الأخضر فمعناه السلامة، مثل طريق الخروج."},{text:"خطر",correct:!1,feedback:"الخطر هو المثلث الأصفر؛ أمّا الإشارة الخضراء فمعناها السلامة، مثل طريق الخروج."},{text:"قف",correct:!1,feedback:"الإشارة الخضراء لا تعني «قف»؛ فالأخضر سلامة، والسهم يدلّ على طريق الخروج."}]},quiz:[{question:"ماذا تعني الدائرة الحمراء التي يقطعها خط؟",options:[{text:"ممنوع / لا تفعل",correct:!0,feedback:"الدائرة الحمراء التي يقطعها خط تقول لك: لا تفعل هذا."},{text:"امشِ",correct:!1,feedback:"الدائرة الحمراء التي يقطعها خط معناها «لا تفعل»، ولا تعني «امشِ» أبدًا."},{text:"خطر",correct:!1,feedback:"الخطر يُعرف بالمثلث الأصفر؛ أمّا الدائرة الحمراء التي يقطعها خط فمعناها «لا تفعل»."}],explanation:"الدائرة الحمراء التي يقطعها خطٌّ أحمر معناها: لا تفعل هذا! أمّا المثلث الأصفر فمعناه خطر، والأخضر معناه السلامة."}]},{id:14,icon:"School",accent:"#0d9488",title:"تدريب الطوارئ في المدرسة",subtitle:"الاستعداد للحوادث",grades:"3-4",ages:"8-10",summary:"تدريب الطوارئ يُعِدّنا لحوادث مثل الحريق والزلزال، لكي نعرف ماذا نفعل عندما تحدث فعلًا.",blocks:[{heading:"استمع إلى المعلّم",body:"استمع دائمًا إلى تعليمات المعلّم.",image:"media/images/listen_teacher.png"},{heading:"اخرج بنظام",body:"لا تدفع أحدًا. اخرج بنظامٍ وبالدور، وساعد من هم أصغر منك.",image:"media/images/orderly_exit.png"},{heading:"نقطة التجمع",body:"ابقَ في نقطة التجمع، وانتظر حتى يقرأ المعلّم اسمك.",image:"media/images/assembly_wait.png"}],examples:["استمع إلى المعلّم.","اخرج بنظام.","ساعد زملاءك.","ابقَ في نقطة التجمع."],tips:["تعامل مع التدريب كأنه حالة طوارئ حقيقية.","تعلّم طرق الخروج.","تحدّث مع زملائك عن خطة الإخلاء."],warnings:["لا تنظر إلى التدريب على أنه لعبة! فهو لحماية حياتك."],realCase:"في أحد الأيام، اندلع حريقٌ في إحدى المدارس. فخرج التلاميذ بهدوء وأمان، لأنهم كانوا قد تدرّبوا من قبل!",video:"media/videos/lesson_drill.mp4",game:{instruction:"ماذا نفعل أثناء التدريب؟",items:[{text:"نستمع إلى المعلّم",emoji:"👂",correct:!0},{text:"نلعب",emoji:"🎮",correct:!1},{text:"نخرج بنظام",emoji:"🚶",correct:!0},{text:"نجمع أغراضنا",emoji:"🎒",correct:!1}]},activity:{prompt:"رنّ جرس الإنذار في أثناء الدرس. ماذا ستفعل؟",image:"media/images/activity_drill.png",options:[{text:"أترك كل شيء وأخرج بنظام",correct:!0,feedback:"بالخروج بنظام ومن دون دفع، يخرج الجميع بأمان."},{text:"أجمع أغراضي",correct:!1,feedback:"أغراضك يمكن أن تنتظر؛ اترك كل شيء واخرج بنظام."},{text:"أبقى في الصف",correct:!1,feedback:"تعامل مع كل جرس إنذار كأنه حالة طوارئ حقيقية؛ اخرج وانتظر في نقطة التجمع."},{text:"أبقى لأرى ماذا سيحدث",correct:!1,feedback:"الجرس يقول: اخرج الآن! فلا تنتظر، واذهب إلى نقطة التجمع."}]},quiz:[{question:"عندما يرنّ جرس الإنذار، ما أول شيء نفعله؟",options:[{text:"اترك كل شيء واخرج",correct:!0,feedback:"بترك كل شيء تخرج بسرعة وبأمان."},{text:"اجمع أغراضك",correct:!1,feedback:"جمع الأغراض يؤخّرك؛ اترك كل شيء واخرج."},{text:"ابقَ في الصف",correct:!1,feedback:"عندما يرنّ الجرس، يذهب الجميع إلى نقطة التجمع، كي لا يبقى أحدٌ في الداخل."}],explanation:"عندما يرنّ جرس الإنذار، اترك كل شيء واخرج بنظامٍ وبالدور. ثم انتظر في نقطة التجمع حتى يقرأ المعلّم اسمك."}]},{id:15,icon:"Award",accent:"#4f46e5",title:"بطل السلامة",subtitle:"المسؤولية والمساعدة",grades:"5-6",ages:"10-12",summary:"بطل السلامة شخصٌ مسؤول، يساعد الناس، ويتصرّف تصرّفًا صحيحًا. والبطل الحقيقي لا يعرّض نفسه للخطر، بل يُخبر الكبار.",blocks:[{heading:"المسؤولية",body:"ينتبه إلى سلامته وسلامة أصدقائه، ويكون يقظًا دائمًا.",image:"media/images/responsibility.png"},{heading:"المساعدة",body:"يساعد من هم أصغر منه، والأشخاص الذين يحتاجون إلى المساعدة.",image:"media/images/help_others.png"},{heading:"تعليم الآخرين",body:"علِّم أصدقاءك ما تتعلّمه. وبهذه الطريقة تزداد المعرفة!",image:"media/images/teach_friends.png"}],examples:["كن مسؤولًا.","ساعد الآخرين.","علِّم أصدقاءك.","كن قدوةً حسنة."],tips:["تعلّم أشياء جديدة.","إذا رأيت خطرًا، فأخبر المعلّم.","كن قدوةً حسنة لأصدقائك."],warnings:["البطل لا يعرّض نفسه للخطر! البطولة هي أن تساعد بذكاء، وأن تُخبر الكبار."],realCase:"علّمت تلميذةٌ في الصف السادس زملاءها الرقمَ 115 وخطةَ الإخلاء. وبعد ذلك، عندما اندلع حريقٌ في المدرسة، خرج جميع زملائها بأمان!",video:"media/videos/lesson_hero.mp4",game:{instruction:"كيف يكون بطل السلامة؟",items:[{text:"مسؤول",emoji:"💪",correct:!0},{text:"يلعب في أثناء الطوارئ",emoji:"🎮",correct:!1},{text:"يساعد الآخرين",emoji:"🤝",correct:!0},{text:"يختبئ",emoji:"🙈",correct:!1}]},activity:{prompt:"أثناء التدريب، يشعر طفلٌ من الصف الأول بالخوف. ماذا ستفعل؟",image:"media/images/activity_hero.png",options:[{text:"أمسك يده، وأريه الطريق بهدوء",correct:!0,feedback:"مساعدة طفلٍ أصغر بهدوء هي ما يفعله بطل السلامة."},{text:"أتركه وأركض",correct:!1,feedback:"الطفل الصغير يحتاج إلى المساعدة ليخرج؛ كن هادئًا وأرِه الطريق."},{text:"أضحك عليه",correct:!1,feedback:"الطفل الخائف يحتاج إلى اللطف؛ أمسك يده وأرِه الطريق بهدوء."},{text:"لا أفعل شيئًا",correct:!1,feedback:"بطل السلامة يساعد من هم أصغر منه؛ أمسك يده وأرِه الطريق بهدوء."}]},quiz:[{question:"ماذا يفعل بطل السلامة؟",options:[{text:"يساعد الآخرين، ويعلّم أصدقاءه، ويكون مسؤولًا",correct:!0,feedback:"المساعدة والتعليم والمسؤولية تُبقيك أنت وأصدقاءك في أمان."},{text:"يُنقذ نفسه فقط",correct:!1,feedback:"بطل السلامة ينتبه أيضًا إلى سلامة أصدقائه، ويساعد من هم أصغر منه."},{text:"لا يفعل شيئًا",correct:!1,feedback:"بطل السلامة يقظٌ دائمًا: إذا رأى خطرًا أخبر المعلّم."}],explanation:"بطل السلامة مسؤول، يساعد الآخرين ويعلّم أصدقاءه. والبطل الحقيقي لا يعرّض نفسه للخطر، بل يُخبر الكبار."}]},{id:16,icon:"FlameKindling",accent:"#ea580c",title:"أنواع الحرائق",subtitle:"نظام NFPA: الفئات A وB وC وD وK",grades:"4-6",ages:"9-12",summary:"ليست كل الحرائق متشابهة! وفقًا لنظام NFPA، هناك خمس فئات للحرائق: A (المواد الصلبة)، وB (السوائل والغازات القابلة للاشتعال)، وC (الأجهزة الكهربائية)، وD (المعادن)، وK (زيت الطبخ). وكل فئة تُطفأ بطريقةٍ خاصة. وإذا وقع الماء على الزيت الساخن المشتعل، فإن النار ترتفع بقوة وتنتشر!",blocks:[{heading:"الفئة A: المواد الصلبة",body:"الخشب، والورق، والقماش، والبلاستيك. وهذه الفئة منتشرة كثيرًا في المنازل والمدارس. ويُطفئها الكبار بالماء أو بمطفأة مسحوق ABC.",image:"media/images/fire_class_a.png"},{heading:"الفئة B: السوائل والغازات القابلة للاشتعال",body:"البنزين، والنفط الأبيض (الكيروسين)، ومخفّف الطلاء (التنر)، والكحول، والغاز. وهي خطيرةٌ جدًا! لا تسكب عليها الماء أبدًا، لأن النار تنتشر. ويُطفئ الكبار السوائل المشتعلة بالرغوة، أو بثاني أكسيد الكربون (CO₂)، أو بمسحوق ABC (وللكحول: CO₂ أو مسحوق ABC أو رغوة خاصة مقاومة للكحول، لأن الرغوة العادية لا تنفع معه). أما الغاز فمختلف: يُغلق الكبار الغاز فقط إذا كان ذلك آمنًا. ولا يُطفأ لهب الغاز ما دام الغاز يتسرّب، لأن الغاز قد ينفجر. وإذا لم يمكن إيقاف الغاز بأمان، يخرج الجميع ويتصلون بالرقم 115.",image:"media/images/fire_class_b.png"},{heading:"الفئة C: الأجهزة الكهربائية",body:"الحاسوب، والتلفاز، والأسلاك، والمقابس الكهربائية. لا تسكب عليها الماء، لأن الكهرباء تقتل! يقطع الكبار الكهرباء أولًا، ثم يُطفئون النار بثاني أكسيد الكربون (CO₂) أو بمسحوق ABC. ملاحظة: يستخدم هذا الدرس أحرف النظام الأمريكي NFPA 10 مرجعًا للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ويستخدم النظام الأوروبي (EN 2) أحرفًا أخرى: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",image:"media/images/fire_class_c.png"}],examples:["الفئة A = الخشب والورق والقماش.","الفئة B = البنزين والنفط الأبيض والغاز.","الفئة C = الأجهزة الكهربائية؛ لا تسكب عليها الماء.","الفئة D = المعادن، والفئة K = زيت الطبخ؛ مسحوق ABC لا يصلح لهما."],tips:["من الجيد أن تكون في المنزل مطفأة مسحوق ABC، وأن يعرف الكبار كيف يستخدمونها.","إذا رأيت نارًا، فلا تقترب منها لتعرف ما الذي يحترق: اخرج وأخبر أحد الكبار.","اتصلوا بالرقم 115 عند حدوث أيّ حريق."],warnings:["لا تسكب الماء أبدًا على حريق الزيت (K) أو الحريق الكهربائي (C)!"],realCase:"في أحد المطابخ، اشتعلت النار في الزيت داخل المقلاة. فسكب أحدهم الماء عليها، فارتفعت النار بقوة وانتشرت! وكانت الطريقة الصحيحة أن يُغلق أحد الكبار الغاز، ويضع غطاءً على المقلاة ليقطع عنها الأكسجين. لقد كان هذا حريقًا من الفئة K.",video:"media/videos/lesson_fire_types.mp4",game:{instruction:"أيّ هذه العبارات صحيحة؟ (نظام NFPA)",items:[{text:"الخشب يحترق = الفئة A",emoji:"🪵",correct:!0},{text:"البنزين يحترق = الفئة A",emoji:"🛢️",correct:!1},{text:"الكابل الكهربائي يحترق = الفئة C",emoji:"⚡",correct:!0},{text:"الورق يحترق = الفئة B",emoji:"📄",correct:!1},{text:"زيت المقلاة يحترق = الفئة K",emoji:"🍳",correct:!0}]},activity:{prompt:"رأيت النار قد اشتعلت في أحد حواسيب المدرسة، والمعلّم ينادي: «أحضروا الماء!» ماذا ستفعل؟",image:"media/images/activity_fire_types.png",options:[{text:"أقول: يا أستاذ، لا تسكبوا الماء عليه! هذا حريقٌ كهربائي (الفئة C). ثم نخرج ونتصل بالرقم 115.",correct:!0,feedback:"الكهرباء تقتل، لذلك لا يصلح الماء لحريق كهربائي؛ ثم يخرج الجميع ويتصلون بالرقم 115."},{text:"أُحضر الماء",correct:!1,feedback:"الماء على الحريق الكهربائي (الفئة C) خطر، لأن الكهرباء تقتل؛ أخبر المعلّم واخرج."},{text:"أسكب الماء على الحاسوب",correct:!1,feedback:"الأطفال لا يُطفئون النار، والماء على حريق الحاسوب خطر؛ اخرج واتصلوا بالرقم 115."},{text:"أركض ولا أخبر أحدًا",correct:!1,feedback:"بإخبار الآخرين يبقون هم أيضًا آمنين؛ نبّه المعلّم، واخرجوا معًا، واتصلوا بالرقم 115."}]},quiz:[{question:"إذا اشتعلت النار في البنزين، فماذا يستخدم الكبار؟",options:[{text:"الماء",correct:!1,feedback:"لا! الماء ينشر حريق البنزين."},{text:"الرغوة أو CO₂",correct:!0,feedback:"صحيح! الرغوة أو CO₂ مناسبان للسوائل المشتعلة مثل البنزين (الفئة B)."},{text:"يُهوّون عليها بالورق",correct:!1,feedback:"لا! الهواء يجعل النار أكبر."}]},{question:"أيّ مطفأة تصلح للفئات الثلاث A وB وC؟",options:[{text:"مطفأة الماء",correct:!1,feedback:"لا، الماء يصلح للفئة A فقط."},{text:"مطفأة مسحوق ABC",correct:!0,feedback:"صحيح! مسحوق ABC يصلح للفئات A وB وC، ولكنه لا يصلح للفئتين D وK."},{text:"لا توجد مطفأة كهذه",correct:!1,feedback:"لا، توجد مطفأة مسحوق ABC."}]}]},{id:17,icon:"Siren",accent:"#dc2626",title:"أبطال الدفاع المدني",subtitle:"عمل فريق 115 ومعدّاته",grades:"5-6",ages:"10-12",summary:"الدفاع المدني مؤسسةٌ حكومية تحمي أرواح الناس وممتلكاتهم. وتستجيب فرقه للحرائق والزلازل والفيضانات وأيّ كارثةٍ أخرى. وفي دهوك، فرقه جاهزةٌ ليلًا ونهارًا.",blocks:[{heading:"مهامّهم",body:"إطفاء الحرائق، وإنقاذ الأشخاص العالقين، والمساعدة أثناء الكوارث، وتعليم الناس قواعد السلامة.",image:"media/images/cd_work.png"},{heading:"معدّاتهم",body:"سيارات الإطفاء الحمراء، وخراطيم المياه الطويلة، والسلالم العالية، وأجهزة التنفّس (BA)، والملابس المقاومة للنار.",image:"media/images/cd_equipment.png"},{heading:"كيف تتصل؟",body:`إذا كان بالقرب منك أحدٌ من الكبار، فأخبره. وإن لم يكن، فاتصل بالرقم 115 وقل:
1. أين أنت (العنوان أو مكان قريب منك)
2. ماذا حدث
3. كم عدد المصابين
4. اسمك

لا تُغلق الهاتف حتى يطلبوا منك ذلك.`,image:"media/images/cd_call.png"}],examples:["السيارة الحمراء ذات صفّارة الإنذار = فريق 115 قادم.","السلّم العالي = يساعد رجال الإطفاء على الوصول إلى النوافذ العالية.","جهاز التنفّس = هواءٌ نقي وسط الدخان.","الملابس المقاومة للنار = تحمي الجسم من حرارة النار."],tips:["احفظ الرقم 115.","اعرف عنوان منزلك.","عندما تسمع صفّارة الإنذار، ابتعد عن الطريق وأفسح المجال للسيارة الحمراء."],warnings:["الاتصال بالرقم 115 ليس لعبة! إذا اتصلت دون سبب، فقد يبقى شخصٌ آخر من دون مساعدة."],realCase:"شبّ حريقٌ في أحد المنازل في دهوك، فاتصل أحد الجيران بالرقم 115. فوصل فريق 115 إلى المكان، وأطفأ النار، وأخرج الأشخاص العالقين بأمان.",video:"media/videos/lesson_cd_work.mp4",game:{instruction:"أيّ هذه الأعمال يقوم بها الدفاع المدني؟",items:[{text:"إطفاء الحرائق",emoji:"🔥",correct:!0},{text:"بيع البيتزا في السوق",emoji:"🍕",correct:!1},{text:"إنقاذ الأشخاص العالقين",emoji:"🆘",correct:!0},{text:"تقديم البرامج في التلفاز",emoji:"📺",correct:!1},{text:"تعليم التلاميذ قواعد السلامة",emoji:"🎓",correct:!0},{text:"المساعدة أثناء الفيضان",emoji:"🌊",correct:!0}]},activity:{prompt:"أنت في الشارع وترى دخانًا يخرج من نافذة أحد المنازل، ولا يوجد أحدٌ في الخارج. ماذا ستفعل؟",image:"media/images/activity_cd_call.png",options:[{text:"أبتعد عن المنزل، وأخبر أحد الكبار أو أتصل بنفسي بالرقم 115، وأذكر عنوان المكان",correct:!0,feedback:"الابتعاد يحميك، وبذكر عنوان المكان يصل فريق 115 بسرعة."},{text:"أدخل إلى المنزل لإنقاذ الناس",correct:!1,feedback:"الإنقاذ عمل فريق 115 بمعدّاته؛ والبطل الحقيقي لا يعرّض نفسه للخطر."},{text:"أركض ولا أخبر أحدًا",correct:!1,feedback:"قد يحتاج مَن في الداخل إلى المساعدة، لذلك أخبر أحد الكبار أو اتصل بالرقم 115 واذكر العنوان."},{text:"أبقى بالقرب من المنزل وأتفرّج",correct:!1,feedback:"البقاء قرب المنزل المحترق ليس آمنًا، والتفرّج لا يجلب المساعدة؛ ابتعد واتصل بالرقم 115."}]},quiz:[{question:"ما رقم الدفاع المدني؟",options:[{text:"122",correct:!1,feedback:"لا، الرقم 122 هو رقم الإسعاف."},{text:"115",correct:!0,feedback:"صحيح! الرقم 115 هو رقم الدفاع المدني."},{text:"104",correct:!1,feedback:"لا، الرقم 104 هو رقم الشرطة."}]},{question:"عندما تسمع صفّارة سيارة الإطفاء الحمراء، ماذا تفعل؟",options:[{text:"أركض في وسط الشارع",correct:!1,feedback:"هذا ليس آمنًا!"},{text:"أبتعد عن الطريق وأفسح لها المجال",correct:!0,feedback:"صحيح! أفسح الطريق لسيارة الدفاع المدني."},{text:"أركض خلف السيارة",correct:!1,feedback:"هذا ليس آمنًا!"}]}]},{id:18,icon:"ShieldAlert",accent:"#c2410c",title:"أجسام خطرة: الألغام والذخائر غير المنفجرة",subtitle:"لا تلمس، ابتعد، أخبر شخصًا كبيرًا",grades:"1-6",ages:"6-12",summary:"بعد الحرب، قد تبقى بعض الأجسام الغريبة في الأرض سنوات طويلة. وبعضها قد ينفجر، حتى لو بدا قديمًا أو صدئًا. وبضع قواعد سهلة تحميك وتحمي أصدقاءك.",blocks:[{heading:"الأجسام الغريبة قد تنفجر",body:"قد تكون الألغام والمتفجرات الأخرى كبيرة أو صغيرة، وبأي شكل أو لون. بعضها يشبه الألعاب أو العلب أو قطع الحديد القديمة. وقد تختبئ بين الأعشاب أو في التراب أو في المباني القديمة. ولا يمكنك أن تعرف بالنظر إن كانت آمنة."},{heading:"قواعد السلامة",body:`• لا تلمسه، ولا تركله، ولا تلتقطه.
• لا ترمِه بالحجارة.
• لا تقترب لتنظر إليه.
• ابتعد وأبعِد أصدقاءك أيضًا.
• أخبر شخصًا كبيرًا فورًا.`},{heading:"العلامات والأماكن الخطرة",body:"العلامات الحمراء والأسيجة والأشرطة والحجارة الحمراء تدلّ على مكان خطر. لا تتجاوزها أبدًا، ولا تنزع العلامة أبدًا. والمكان الذي لا علامة فيه قد يكون خطرًا أيضًا. امشِ والعب فقط حيث يمشي الناس ويلعبون كل يوم."},{heading:"إذا ظننت أنك في مكان خطر",body:"توقّف. اثبت في مكانك تمامًا. نادِ طلبًا للمساعدة. انتظر حتى يأتي شخص كبير أو منقذ. لا تركض ولا تعُد إلى الوراء."}],examples:["جسم معدني غريب بين الأعشاب = لا تلمسه، وأخبر شخصًا كبيرًا.","علامة حمراء عليها جمجمة = خطر، لا تدخل.","جسم يشبه اللعبة في حقل = اتركه وأخبر شخصًا كبيرًا.","الكبار يتصلون بالرقم 115 = رقم الدفاع المدني."],tips:["امشِ على الطرق والممرات التي يستخدمها الناس كل يوم.","أخبر شخصًا كبيرًا عن كل جسم غريب تراه.","ذكّر أصدقاءك بقواعد السلامة."],warnings:["لا تلمس جسمًا غريبًا أبدًا، ولا تركله، ولا تلتقطه، ولا ترمِه بالحجارة!"],realCase:"في طريق العودة من المدرسة، رأت فتاة جسمًا معدنيًّا غريبًا بجانب الطريق. لم تقترب منه، وطلبت من صديقاتها أن يبقين بعيدًا، ومشين إلى البيت على الطريق. أخبرت أمها، فاتصلت أمها بالرقم 115 وقالت لها: «لقد فعلتِ الصواب!»",game:{instruction:"ترى جسمًا غريبًا. ما الأفعال الآمنة؟",items:[{text:"أخبر شخصًا كبيرًا",emoji:"🗣️",correct:!0},{text:"اركله",emoji:"🦶",correct:!1},{text:"ابتعد",emoji:"🚶",correct:!0},{text:"التقطه",emoji:"✋",correct:!1},{text:"أبعِد أصدقاءك",emoji:"👫",correct:!0},{text:"ارمِه بالحجارة",emoji:"🪨",correct:!1}]},activity:{prompt:"وجدتَ أنت وصديقك جسمًا معدنيًّا غريبًا قرب الملعب، ويريد صديقك أن يلتقطه. ماذا تفعل؟",options:[{text:"أقول: «توقّف، لا تلمسه!»، ثم نبتعد وأخبر شخصًا كبيرًا",correct:!0,feedback:"الأجسام الغريبة قد تنفجر. الابتعاد معًا وإخبار شخص كبير يحميكما كليكما."},{text:"ننظر إليه عن قرب لنعرف ما هو",correct:!1,feedback:"الاقتراب خطر. ابتعد وأخبر شخصًا كبيرًا."},{text:"نرميه بحجارة صغيرة من بعيد",correct:!1,feedback:"رمي أي شيء عليه قد يجعله ينفجر. ابتعد وأخبر شخصًا كبيرًا."},{text:"نأخذه إلى البيت لنريه لعائلتنا",correct:!1,feedback:"لا تحمل جسمًا غريبًا أبدًا: فقد ينفجر. اتركه في مكانه وأخبر شخصًا كبيرًا."}]},quiz:[{question:"ماذا تفعل إذا رأيت جسمًا غريبًا على الأرض؟",options:[{text:"أبتعد وأخبر شخصًا كبيرًا",correct:!0},{text:"ألتقطه وآخذه إلى المعلّم لأريه إياه",correct:!1},{text:"أركله ليبتعد",correct:!1}],explanation:"الأجسام الغريبة قد تنفجر. لا تلمسها ولا تركلها: ابتعد وأخبر شخصًا كبيرًا فورًا."},{question:"ماذا تعني العلامة الحمراء التي عليها جمجمة؟",options:[{text:"خطر: لا تتجاوزها",correct:!0},{text:"مكان جيد للعب الغمّيضة",correct:!1},{text:"طريق مختصر إلى البيت",correct:!1}],explanation:"العلامة الحمراء التي عليها جمجمة تحذّر من الخطر. لا تتجاوزها أبدًا ولا تنزعها أبدًا."},{question:"تظن أنك في مكان خطر. ماذا تفعل؟",options:[{text:"أتوقّف ولا أتحرّك، وأنادي طلبًا للمساعدة، وأنتظر",correct:!0},{text:"أركض بأقصى سرعة أستطيعها لأخرج من هذا المكان",correct:!1},{text:"أعود بحذر شديد على آثار قدميّ نفسها حتى أصل إلى الطريق",correct:!1}],explanation:"عندما تثبت في مكانك لا تطأ جسمًا خطرًا آخر. نادِ طلبًا للمساعدة وانتظر شخصًا كبيرًا أو منقذًا."}]},{id:19,icon:"LifeBuoy",accent:"#0284c7",title:"السلامة في الماء",subtitle:"السباحة واللعب بالقرب من الماء",grades:"1-6",ages:"6-12",summary:"السباحة واللعب في الماء ممتعان، لكن الماء قد يكون خطيرًا. فالأنهار والسدود وقنوات المياه والبرك والمسابح قد تكون عميقة أو باردة أو سريعة الجريان. وقد يحدث الغرق بسرعة وبصمت، لذلك ابقَ دائمًا مع شخص كبير يراقبك.",blocks:[{heading:"الماء قد يكون خطيرًا",body:"الأنهار والسدود وقنوات المياه والبرك والمسابح قد تكون عميقة. وقد يكون الماء باردًا وسريع الجريان، حتى لو بدا هادئًا. ولا يمكنك أن ترى القاع ولا ما يختبئ تحت الماء."},{heading:"دائمًا مع شخص كبير يراقبك",body:"استأذن أحد الكبار قبل أن تقترب من الماء. لا تسبح ولا تلعب في الماء إلا إذا كان معك شخص كبير يراقبك طوال الوقت. لا تسبح وحدك أبدًا، حتى لو كنت تجيد السباحة."},{heading:"قبل أن تنزل إلى الماء",body:"البس سترة نجاة على مقاسك بالقرب من الأنهار والبحيرات والسدود وفي القارب. لا تقفز أبدًا في ماء لا تعرف عمقه: فقد تختبئ تحت الماء صخور أو أماكن ضحلة."},{heading:"إذا كان أحدٌ في خطر في الماء",body:`لا تنزل إلى الماء. اصرخ بصوت عالٍ لتنادي أحد الكبار. ارمِ شيئًا يطفو، مثل كرة أو طوق نجاة، وابقَ بعيدًا عن الحافة. وإذا لم يكن أحد من الكبار قريبًا، فاتصل بالرقم 115.

الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد.`}],examples:["حتى النهر الهادئ قد يكون عميقًا وباردًا وسريع الجريان.","عندما تسبح، يراقبك شخص كبير طوال الوقت.","سترة النجاة التي على مقاسك تساعدك على الطفو.","أحدٌ في خطر في الماء: اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو."],tips:["استأذن أحد الكبار دائمًا قبل أن تقترب من الماء.","لا تسبح وحدك أبدًا.","تعلّم السباحة مع مدرّب مؤهَّل. حتى السبّاحون الماهرون يحتاجون إلى شخص كبير يراقبهم."],warnings:["لا تنزل إلى الماء أبدًا لإنقاذ أحد! اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو."],realCase:"في يوم صيفي حار، كان صديقان بالقرب من قناة مياه. أراد أحدهما أن يقفز في الماء ليبرد جسمه. فرفض الصديق الآخر: فهما لا يعرفان عمق الماء، ولم يكن معهما أحد من الكبار. فعادا إلى البيت وأخبرا والديهما. وفي وقت لاحق، سبحا في مسبح وكان شخص كبير يراقبهما طوال الوقت.",game:{instruction:"أيّ هذه الأفعال آمنة بالقرب من الماء؟ اختر الإجابات الصحيحة:",items:[{text:"استأذن أحد الكبار قبل الاقتراب من الماء",emoji:"🙋",correct:!0},{text:"اسبح وحدك في النهر",emoji:"🌊",correct:!1},{text:"البس سترة نجاة على مقاسك",emoji:"🦺",correct:!0},{text:"اقفز في ماء لا تعرف عمقه",emoji:"🤸",correct:!1},{text:"اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو",emoji:"📣",correct:!0},{text:"انزل إلى الماء لإنقاذ صديقك",emoji:"🏊",correct:!1}]},activity:{prompt:"أنت تلعب مع صديقك بالقرب من بركة. انزلق صديقك وسقط في الماء العميق. ماذا ستفعل؟",options:[{text:"لا أنزل إلى الماء، وأصرخ بصوت عالٍ لأنادي أحد الكبار، وأرمي شيئًا يطفو",correct:!0,feedback:"الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد. الصراخ يجلب أحد الكبار، والشيء الذي يطفو يساعد صديقك على البقاء فوق الماء."},{text:"أقفز في الماء وأُخرج صديقي",correct:!1,feedback:"إذا نزلت إلى الماء فقد تغرق أنت أيضًا. ابقَ خارج الماء، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو."},{text:"أنحني فوق الحافة وأمسك يد صديقي",correct:!1,feedback:"قد تنزلق أنت أيضًا أو تُسحب إلى الماء. ابتعد عن الحافة، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو."},{text:"أركض إلى البيت من الخوف ولا أخبر أحدًا",correct:!1,feedback:"صديقك يحتاج إلى المساعدة بسرعة. اصرخ فورًا لتنادي أحد الكبار؛ وإذا لم يكن أحد منهم قريبًا، فاتصل بالرقم 115."}]},quiz:[{question:"عندما تسبح أو تلعب بالقرب من الماء، من يجب أن يكون معك؟",options:[{text:"شخص كبير يراقبك طوال الوقت",correct:!0},{text:"صديق في مثل عمرك يجيد السباحة",correct:!1},{text:"لا أحد، إذا كنت تجيد السباحة من قبل",correct:!1}],explanation:"قد يحدث الغرق بسرعة وبصمت. يجب أن يكون شخص كبير قريبًا منك ويراقبك طوال الوقت، حتى لو كنت تعرف السباحة."},{question:"صديقك في خطر في الماء. ماذا تفعل؟",options:[{text:"لا تنزل إلى الماء، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو",correct:!0},{text:"اقفز بسرعة في الماء واسحب صديقك إلى حافة الماء",correct:!1},{text:"ابقَ صامتًا على الحافة حتى يخرج صديقك من الماء وحده",correct:!1}],explanation:"الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد. الصراخ يجلب أحد الكبار، والشيء الذي يطفو يساعد صديقك على البقاء فوق الماء."},{question:"تريد أن تقفز في نهر، لكنك لا تعرف عمقه. ما التصرف الصحيح؟",options:[{text:"لا تقفز: فقد تختبئ تحت الماء صخور أو أماكن ضحلة",correct:!0},{text:"اقفز، لأن الأطفال الأكبر سنًّا يقفزون في الماء هناك",correct:!1},{text:"اقفز برأسك أولًا حتى تصل إلى الماء العميق بسرعة",correct:!1}],explanation:"لا يمكنك أن ترى ما تحت الماء. فالصخرة المختبئة أو المكان الضحل قد يسببان إصابة خطيرة جدًّا. لا تقفز أبدًا في ماء لا تعرف عمقه."}]}],t={lessons:e};export{t as default,e as lessons};
